type ExpressionDetails = { offset: number; unit: string };

// Time input formats that are accepted by the date-picker (in addition to ISO string)
// Missing information is automatically added using 'startOfToday'
const TIME_INPUT_FORMATS = [
  'yyyy-MM-dd',
  'yyyy-MM-dd H:mm',
  'yyyy-MM-dd H:mm:ss',
  'H:mm',
  'H:mm:ss',
];

// for provided iso8601 format, only allow UTC timezone
const UTC_ISO_TIME_EXPRESSION =
  /(?<iso>^\d{4}-[01]\d-[0-3]\dT[0-2]\d:[0-5]\d:[0-5]\d(\.\d{1,3})?)(?<extended_precision>\d*)(?<timezone>Z)$/;

// The corresponding regex playground can be found here: https://regex101.com/r/kbBBaP/1
/** @internal */
export const _TIMEFRAME_EXPRESSION =
  /^(?!\s*$)((?:now)(?:\(\))?)?\s*(?:([+-]\s*\d+)\s*(d|m|h|s|ms))?\s*$/i;

/**
 * Timeframe expression but but for compatiblity, extended to support weeks, month and years as unit
 * @internal
 * @deprecated - only included for compatibilty reasons to support the old expression format for a while longer.
 */
export const _TIMEFRAME_EXPRESSION_COMPATIBILITY =
  /^(?!\s*$)((?:now)(?:\(\))?)?\s*(?:([+-]\s*\d+)\s*(d|m|h|s|ms|w|M|y))?\s*$/i;

