/**@internal */
export function _isExpressionString(candidate: string) {
  const [expression] = candidate.match(_TIMEFRAME_EXPRESSION) ?? [];
  return !!expression;
}

/**
 * Parses the input for expression details.
 * @internal
 */
export function _parseTimeExpression(
  candidate: string,
): ExpressionDetails | undefined {
  const [expression, , offset, unit] =
    candidate.match(_TIMEFRAME_EXPRESSION) ?? [];

  if (expression) {
    const sanitizedOffset = offset ? parseInt(offset.replace(/\s/g, '')) : 0;
    return { offset: sanitizedOffset, unit };
  }
}

/**
 * Converts expression details into a date object
 * @internal
 */
export function _getDateFromExpression(
  { offset, unit }: ExpressionDetails,
  relativeDate: number,
): Date | null {
  const now = new Date(relativeDate);
  switch (unit) {
    case 'ms':
      return addMilliseconds(now, offset);
    case 's':
      return addSeconds(now, offset);
    case 'm':
      return addMinutes(now, offset);
    case 'h':
      return addHours(now, offset);
    case 'd':
      return addDays(now, offset);
  }

  return null;
}

/** Generates a date object out of the input string if provided in one of the accepted formats */
function parseDatetimeInput(candidate: string): Date | null {
  const referenceDate = startOfToday();

  for (const format of TIME_INPUT_FORMATS) {
    const date = parse(candidate, format, referenceDate);
    if (isValid(date)) {
      return date;
    }
  }

  return null;
}

/**
 * Checks if the provided value is a valid ISO string with support for extended (up tp nano) precision.
 * We cannot use dateFns parseISO because it returns native Date object, which do not support extended precision.
 */
function parseISOWithExtendedPrecision(candidate: string): TimeValue | null {
  const match = candidate.match(UTC_ISO_TIME_EXPRESSION);
  if (!match?.groups) {
    return null;
  }

  const iso = match.groups['iso'];
  /* contains all precision digits smaller than milli seconds */
  const extended_precision = match.groups['extended_precision'] ?? '';
  const timezone = match.groups['timezone'];

  return {
    type: 'iso8601',
    value: `${iso}${extended_precision}${timezone}`,
    absoluteDate: `${iso}${extended_precision}${timezone}`,
  };
}

function _getTimeValue(candidate?: TimeValue | string): TimeValue | undefined {
  if (candidate === undefined) {
    return undefined;
  }

  if (typeof candidate === 'string') {
    const parsed = _parseTime(candidate);

    // Invalid expression returns broken TimeValue to show errors.
    if (!parsed) {
      return { absoluteDate: '', value: candidate, type: 'expression' };
    }

    // Parsing did return a valid TimeValue
    return parsed;
  }

  // In this case the candidate is already a TimeValue
  return candidate;
}

export function _mapToTimeframeV2(
  value:
    | RequireAtLeastOne<{ from: string; to: string }>
    | RequireAtLeastOne<TimeframeV2>,
): RequireAtLeastOne<TimeframeV2> | null {
  const from = _getTimeValue(value.from);
  const to = _getTimeValue(value.to);

  // Satisfies the RequiredAtLeastOne
  if (from === undefined && to === undefined) {
    return null;
  }

  return {
    from,
    to,
  } as RequireAtLeastOne<TimeframeV2>;
}

/**
 * You can use the `_parseValue` utility function to convert a Timeframe or TimeframeV2 value into an object containing `from` and `to`
 * `TimeValue`s or null values. If `fallbackToNow` is set to true, the `to` value falls back to `now` in case the to value is empty.
 * @internal
 */
export function _parseValue(
  value: Timeframe | RequireAtLeastOne<TimeframeV2> | null,
  fallbackToNow: boolean = false,
): {
  from: TimeValue | null;
  to: TimeValue | null;
} {
  const nowDate = {
    value: 'now()',
    absoluteDate: new Date().toISOString(),
    type: 'expression',
  } as TimeValue;

  if (!value) {
    return { from: null, to: fallbackToNow ? nowDate : null };
  }

  const { valueFrom, valueTo } = _getFromToValues(value);
  const from = _parseTime(valueFrom);
  const to = fallbackToNow && !valueTo ? nowDate : _parseTime(valueTo);

  return { from, to };
}

/**
 * You can use the `parseTime` utility function to convert a string into
 * `TimeValue`, giving you a normalized version of the input string (trimmed
 * string), a `Date` object created from the given input, and the type of input.
 * The type can be either an `expression` or `iso8601` string. If it is not
 * possible to convert the input, the function will return `null`.
 * @internal
 */
export function _parseTime(
  candidate?: string | null,
  relativeDate: number = Date.now(),
): TimeValue | null {
  if (!candidate) {
    return null;
  }

  const value = candidate.trim();

  // Check for 'now' expression
  if (value.toLowerCase() === 'now' || value.toLowerCase() === 'now()') {
    return {
      type: 'expression',
      value: 'now()',
      absoluteDate: new Date(relativeDate).toISOString(),
    };
  }

  // Check for time expression format
  const timeDetails = _parseTimeExpression(value);
  if (timeDetails) {
    const absoluteDate = _getDateFromExpression(timeDetails, relativeDate);
    const { offset, unit } = timeDetails;

    // In case we don't have any offset, a simple now is good enough
    if (offset === 0) {
      return {
        type: 'expression',
        value: 'now()',
        absoluteDate: new Date(relativeDate).toISOString(),
      };
    }

    return absoluteDate && isValid(absoluteDate)
      ? {
          type: 'expression',
          value: `now()${offset < 0 ? offset : `+${offset}`}${unit}`,
          absoluteDate: absoluteDate.toISOString(),
        }
      : null;
  }

  // Check if input was already provided as ISO string
  const parsedISODateDetails = parseISOWithExtendedPrecision(value);

  if (parsedISODateDetails) {
    return parsedISODateDetails;
  }

  // Check for supported date format
  const date = parseDatetimeInput(value);
  if (date) {
    return {
      type: 'iso8601',
      absoluteDate: date.toISOString(),
      value: date.toISOString(),
    };
  }

  return null;
}

/**
 * Formatter that displays sanitized time value strings.
 * @internal
 */
export function _formatTimeValue(
  input: TimeValue | Omit<TimeValue, 'absoluteDate'> | string,
  precision: TimeframeSelectorBaseProps['precision'] = 'minutes',
) {
  if (input === 'now()' || input === 'now') {
    return 'Now'; // early exit to prevent parsing if we already know we should return 'Now'
  }

  const timeValue = _parseTime(typeof input == 'string' ? input : input.value);

  if (timeValue === null) {
    return '';
  }

  const { type, value } = timeValue;

  if (type === 'iso8601') {
    return _getFormattedTimeValue(timeValue, precision);
  }

  if (value === 'now()') {
    return 'Now';
  }

  return value.replaceAll('now()', '').replaceAll('now', '').trim();
}

/**
 * Formatter that gets the formatted time value strings.
 * @internal
 */
export function _getFormattedTimeValue(
  timeValue: TimeValue | null,
  precision?: TimeframeSelectorBaseProps['precision'],
  showTimeOnly?: boolean,
) {
  const formatOptions: FormatDateOptions = {
    // Extract the user-settings timezone to use for the calculation
    timeZone: getTimezone(),
    hourCycle: 'h23',
    second:
      precision === 'seconds' || precision === 'milliseconds'
        ? '2-digit'
        : undefined,
    minute: '2-digit',
    day: showTimeOnly ? undefined : 'numeric',
    month: showTimeOnly ? undefined : 'short',
    year: showTimeOnly ? undefined : 'numeric',
    hour: '2-digit',
    fractionalSecondDigits: precision === 'milliseconds' ? 3 : undefined,
  };

  const absoluteDate = timeValue?.absoluteDate
    ? new Date(timeValue.absoluteDate)
    : null;

  return absoluteDate && isValid(absoluteDate)
    ? formatDate(absoluteDate, formatOptions)
    : '';
}

/**
 * Returns the formatted relative expression for the given time values.
 * @internal
 */
function _formatRelativeExpressions(
  from: TimeValue,
  to: TimeValue,
  intl: IntlShape,
): string | undefined {
  if (to.value === from.value) {
    return intl.formatMessage(messages.invalid);
  }

  if (to.value === 'now()') {
    return _formatRelativeToNow(from.value, intl, 'past');
  } else if (from.value === 'now()') {
    return _formatRelativeToNow(to.value, intl, 'future');
  }
}

/**
 * Returns the from and to string values from a TimeframeV2 or a Timeframe.
 * @internal
 */
export function _getFromToValues(
  value?: Partial<Timeframe> | RequireAtLeastOne<TimeframeV2>,
) {
  if (!value) {
    return {};
  }

  const valueFrom =
    typeof value.from === 'string' ? value.from : value.from?.value;
  const valueTo = typeof value.to === 'string' ? value.to : value.to?.value;

  return { valueFrom, valueTo };
}

/**
 * Returns the display value string for a given timeframe.
 * @internal
 */
export function _formatTimeframe(
  value: TimeframeV2 | TimeframeSelectorPresetItemProps['value'],
  intl: IntlShape,
  precision?: 'minutes' | 'seconds' | 'milliseconds',
) {
  const { valueFrom, valueTo } = _getFromToValues(value);
  const fromDetails = _parseTime(valueFrom);
  const toDetails = _parseTime(valueTo);

  return _extractDisplayValueFromTimeValues(
    fromDetails,
    toDetails,
    intl,
    precision,
    valueFrom,
    valueTo,
  );
}

/**
 * Extracts the display value string from the from and to time values.
 * @internal
 */
export function _extractDisplayValueFromTimeValues(
  from: TimeValue | null,
  to: TimeValue | null,
  intl: IntlShape,
  precision: 'minutes' | 'seconds' | 'milliseconds' = 'minutes',
  valueFrom?: string,
  valueTo?: string,
) {
  let hint = '';

  if (!from || !to) {
    process.env.NODE_ENV === 'development' &&
      !from &&
      // eslint-disable-next-line no-console
      console.warn(
        `The from date could not be parsed. Please check if the provided value is valid and supported: ${valueFrom}.`,
      );
    !to &&
      // eslint-disable-next-line no-console
      console.warn(
        `The to date could not be parsed. Please check if the provided value is valid and supported: ${valueTo}.`,
      );

    if (!from && !to) {
      hint = intl.formatMessage({
        defaultMessage: 'Invalid timeframe',
        id: 'U59PIse3upSvDblc',
        description:
          'Error message shown if the from and to values of a timeframe are both invalid',
      });
    } else if (!from) {
      hint = intl.formatMessage(messages.invalidFrom);
    } else {
      hint = intl.formatMessage(messages.invalidTo);
    }

    return {
      displayValue: intl.formatMessage(messages.invalid),
      isInvalid: true,
      hint,
    };
  }

  const fromDate = new Date(from.absoluteDate);
  const toDate = new Date(to.absoluteDate);

  const { isInvalid, hint: invalidItemHint } = _checkInvalidItem(
    fromDate,
    toDate,
    from.value,
    to.value,
    intl,
  );

  if (isInvalid) {
    return {
      displayValue: intl.formatMessage(messages.invalid),
      isInvalid: true,
      hint: invalidItemHint,
    };
  }

  if (from.type === 'expression' && to.type === 'expression') {
    const formatted = _formatRelativeExpressions(from, to, intl);
    if (formatted) {
      return { displayValue: formatted, isInvalid: false, hint };
    }
  }

  const isToSameDay = isSameDay(fromDate, toDate);

  return {
    displayValue: `${_formatDetails(from, intl, precision)} → ${_formatDetails(
      to,
      intl,
      precision,
      isToSameDay,
    )}`,
    isInvalid: false,
    hint,
  };
}

/**
 * Checks if the preset item is invalid and logs a warning in dev mode.
 * @internal
 */
function _checkInvalidItem(
  fromDate: Date,
  toDate: Date,
  from: string,
  to: string,
  intl: IntlShape,
) {
  if (!isValid(fromDate)) {
    process.env.NODE_ENV === 'development' &&
      // eslint-disable-next-line no-console
      console.warn(`The from date (${from}) is invalid.`);
    return { isInvalid: true, hint: intl.formatMessage(messages.invalidFrom) };
  }

  if (!isValid(toDate)) {
    process.env.NODE_ENV === 'development' &&
      // eslint-disable-next-line no-console
      console.warn(`The to date (${to}) is invalid.`);
    return { isInvalid: true, hint: 'The to date is invalid.' };
  }

  if (isBefore(toDate, fromDate)) {
    process.env.NODE_ENV === 'development' &&
      // eslint-disable-next-line no-console
      console.warn(
        `The from date - ${from} - should be before the to date - ${to}.`,
      );
    return { isInvalid: true, hint: intl.formatMessage(messages.invalidOrder) };
  }

  return { isInvalid: false, hint: '' };
}

/**
 * Returns expression in e.g. 'Last 5 minutes' format.
 * @internal
 */
function _formatRelativeToNow(
  expression: string,
  intl: IntlShape,
  prefix?: 'future' | 'past',
): string {
  const [, , offsetString, unit] =
    expression.match(_TIMEFRAME_EXPRESSION) ?? [];
  const offset = offsetString
    ? Math.abs(parseInt(offsetString.replace(/\s*/g, '')))
    : 0;

  if (offset === 0) {
    return intl.formatMessage(messages.now);
  }

  const timeExpression = messages[unit as keyof typeof messages];

  if (timeExpression) {
    prefix ??= offsetString.includes('+') ? 'future' : 'past';
    return intl.formatMessage(timeExpression, { prefix, offset });
  }

  return intl.formatMessage(messages.invalid);
}

export function _formatDetails(
  details: TimeValue,
  intl: IntlShape,
  precision: TimeframeSelectorBaseProps['precision'] = 'minutes',
  showTimeOnly?: boolean,
): string {
  return details.type === 'expression'
    ? _formatRelativeToNow(details.value, intl)
    : _getFormattedTimeValue(details, precision, showTimeOnly);
}

/**
 * Gets the formatted min and max values that are used in the translated messages.
 * @internal
 */
export function _getFormattedMinMax(
  min?: string,
  max?: string,
  precision?: TimeframeSelectorBaseProps['precision'],
) {
  const minDate = max ? _parseTime(min) : null;
  const maxDate = max ? _parseTime(max) : null;
  const formattedMin = _getFormattedTimeValue(minDate, precision);
  const formattedMax = _getFormattedTimeValue(
    maxDate,
    precision,
    !!minDate &&
      !!maxDate &&
      isSameDay(new Date(minDate.absoluteDate), new Date(maxDate.absoluteDate)),
  );

  return {
    min: formattedMin,
    max: formattedMax,
  };
}

/**
 * Converts timeframe expression containing weeks, month or years into expressions using days.
 * @deprecated - only included for compatibilty reasons to support the old expression format for a while longer.
 * @internal
 */
export function _migrateDeprecatedExpression(input: string) {
  const match = input
    .replace(/\s+/g, '')
    .match(_TIMEFRAME_EXPRESSION_COMPATIBILITY);
  if (!match) {
    return input;
  }

  const [, now = '', offset, unit] = match;

  if (offset === undefined || unit === undefined) {
    return input;
  }

  const nOffset = parseInt(offset);

  switch (unit) {
    case 'w':
      return `${now}${nOffset > 0 ? '+' : ''}${nOffset * 7}d`;
    case 'M':
      return `${now}${nOffset > 0 ? '+' : ''}${nOffset * 30}d`;
    case 'y':
      return `${now}${nOffset > 0 ? '+' : ''}${nOffset * 365}d`;
    default:
      return input;
  }
}
